//! KeePass icon rendering: the 69 standard icons (rasterized from the
//! original KeePassXC SVGs) plus database custom icons, uploaded to egui
//! textures on demand.

use std::collections::HashMap;

use eframe::egui::{ColorImage, Context, TextureHandle, TextureOptions};
use keepass::db::Icon;

// Generated by build.rs from `icons/`.
include!(concat!(env!("OUT_DIR"), "/icons.rs"));

/// Default icon numbers (same as KeePass): key for entries, folder for groups.
pub const DEFAULT_ENTRY_ICON: usize = 0;
pub const DEFAULT_GROUP_ICON: usize = 48;

/// Something drawable: a standard icon number or custom icon bytes.
#[derive(Clone)]
pub enum IconSpec {
    Standard(usize),
    Custom { key: String, bytes: Vec<u8> },
}

/// Resolve the icon of an entry/group for rendering, with KeePass's default.
pub fn icon_spec(db: &keepass::db::Database, icon: Option<&Icon>, default: usize) -> IconSpec {
    match icon {
        Some(Icon::BuiltIn(n)) => IconSpec::Standard(*n),
        Some(Icon::Custom(id)) => match db.custom_icon(*id) {
            Some(ci) => IconSpec::Custom {
                key: format!("custom-{id}"),
                bytes: ci.data.clone(),
            },
            None => IconSpec::Standard(default),
        },
        None => IconSpec::Standard(default),
    }
}

/// Decodes PNG/JPEG bytes into an egui color image.
pub fn decode_image_bytes(bytes: &[u8]) -> Option<ColorImage> {
    let img = image::load_from_memory(bytes).ok()?.to_rgba8();
    let size = [img.width() as usize, img.height() as usize];
    Some(ColorImage::from_rgba_unmultiplied(size, img.as_raw()))
}

/// Lazily-uploaded texture cache for icons.
#[derive(Default)]
pub struct IconCache {
    map: HashMap<String, TextureHandle>,
}

impl IconCache {
    pub fn texture(&mut self, ctx: &Context, key: &str, bytes: &[u8]) -> Option<TextureHandle> {
        if let Some(t) = self.map.get(key) {
            return Some(t.clone());
        }
        let image = decode_image_bytes(bytes)?;
        let tex = ctx.load_texture(key, image, TextureOptions::default());
        self.map.insert(key.to_owned(), tex.clone());
        Some(tex)
    }

    pub fn standard(&mut self, ctx: &Context, n: usize) -> Option<TextureHandle> {
        let (_, bytes) = STANDARD_ICONS.iter().find(|(i, _)| *i == n)?;
        self.texture(ctx, &format!("std-{n}"), bytes)
    }

    pub fn spec(&mut self, ctx: &Context, spec: &IconSpec) -> Option<TextureHandle> {
        match spec {
            IconSpec::Standard(n) => self.standard(ctx, *n),
            IconSpec::Custom { key, bytes } => self.texture(ctx, key, bytes),
        }
    }
}

/// Render an icon (16x16) into the current UI, if it can be resolved.
pub fn draw_icon(ui: &mut eframe::egui::Ui, cache: &mut IconCache, spec: Option<&IconSpec>) {
    if let Some(spec) = spec {
        let ctx = ui.ctx().clone();
        if let Some(tex) = cache.spec(&ctx, spec) {
            ui.add(eframe::egui::Image::new((tex.id(), eframe::egui::Vec2::splat(16.0))));
            return;
        }
    }
    // Placeholder keeps the layout stable even without a resolvable icon.
    ui.add_space(16.0);
}
